let seed;
let mySize, margin;
let num;
let myGraphic;
let palette, color_bg;
let str_wei;

let unit_x, unit_y;
let count;
let t;
let mods = [];
let a, b, c;

function setup() {
	a = TAU / TAU;
	b = a + a;
	c = a - a;
	seed = Math.random() * sq(sq(sq(int(TAU))));
	randomSeed(seed);

	mySize = max(windowWidth, windowHeight) * 0.9;
	createCanvas(windowWidth, windowHeight, WEBGL);

	perspective(0.5, width / height, 5, 10000);
	palette = random(colorScheme).colors.concat();
	color_bg = random(bgcolor);
	background(color_bg);
	frameRate(50);
	t = rez = c = n = c;
}

function draw() {
	randomSeed(seed);
	background(color_bg);

	push();
	translate(0, 0, -mySize * 4.0);
	// rotateX(random(TAU));
	rotateY(random(TAU));
	// rotateZ(random(TAU));


	rotateX(random([-1, 1]) * frameCount / 100);
	rotateY(random([-1, 1]) * frameCount / 100);
	rotateZ(random([-1, 1]) * frameCount / 100);

	let pNum2 = 200;
	for (let p = 0; p < pNum2; p++) {
		let ttt = sin(t) * sin(t) * cos(t);
		let yt = 13 * cos(t) - 5 * sin(2 * t) - 2 * cos(3 * t) - cos(4 * t);
		translate(ttt * 16, yt, 0);
		// translate(p * random(1.1, 10.25) + sin(t / 1) * 10, 
		// 					p * random(1.1, 10.25) + tan(t / 1) * 10, 
		// 					p * random(1.1, 10.25) + cos(t / 1) * 10);
		rotateX(360 / pNum2 * p);
		rotateY(360 / pNum2 * p);
		rotateZ(360 / pNum2 * p);
		noFill();
		stroke(random(palette));
		strokeWeight(random(1, 10));
		let lSize = mySize / random(50, 5);
		// heart(0,0,100);
		// point(0, 0, 0);
		point(lSize, lSize, lSize);
		strokeWeight(random(10.1, 1.2));

		push();
		translate(p * random(1.1, 0.25) + sin(t / 1) * 2, p * random(1.1, 0.25) + sin(t / 1) * 2, p * random(1.1, 0.25) + sin(t / 1) * 2);
		rotateX(random([-1, 1]) * frameCount / 50);
		rotateY(random([-1, 1]) * frameCount / 50);
		rotateZ(random([-1, 1]) * frameCount / 50);
		lSize = lSize / 1.1;
		line(-lSize, lSize, lSize, lSize, lSize, lSize);
		pop();
	}

	let cubeSize = mySize / (a + a / b) / 2.0;
	let plus = cubeSize / 2;

		for (let i = -cubeSize / b; i < cubeSize / b*2 + plus; i += plus * a) {
			for (let j = -cubeSize / b; j < cubeSize / b + plus; j += plus * a) {
				for (let k = -cubeSize / b; k < cubeSize / b + plus; k += plus * a) {

					strokeCap(PROJECT);
					n = noise(i * rez + t, j * rez + t, k * rez + t) * random(0.1, 3);

					push();
					translate(i * n, j * n, k * n);
					// translate(i * 1, j * 1, k * 1);
					let pNum = 5;
					for (let p = 0; p < pNum; p++) {
						// translate(i * 1, j * 1, k * 1);
						translate(p * 0.7, p * 0.3, p * 0.5);
						translate(i * n, j * n, k * n);
						rotateX(360 / pNum * p);
						rotateY(360 / pNum * p);
						rotateZ(360 / pNum * p);
						noFill();
						stroke(random(palette));
						strokeWeight(1*random(1,2));
						let llSize = mySize / random(200, 100);
						line(0, 0, 0, llSize, llSize, llSize);
					}


					rotateX(TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));
					rotateY(TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));
					rotateZ(TAU / (b * b) * random([-a, a, b, -b]) * random([a, b, a + b, b * b]));

					switch (random([1, 2, 3])) {
						case 1:
							rotateX(1 * random([-1, 1]) * frameCount / 10);
							break;
						case 2:
							rotateY(1 * random([-1, 1]) * frameCount / 100);
							break;
						case 3:
							rotateZ(n * random([-1, 1]) * frameCount / 100);
							break;
					}


					let planeSize = mySize / random([16, 32, 8]);
					push();
					translate(i, j, k);

					switch (random([1, 2])) {
						case 1:
							noStroke();
							fill(random(palette));
							// plane(planeSize / 1);
							sphere(planeSize / 10);

							break;
						case 2:
							noFill();
							stroke(random(palette));
							strokeWeight(random(1, 2));
							switch (random([1, 2, 3, 4])) {
								case 1:
									line(-planeSize / 2, -planeSize / 2, planeSize / 2, -planeSize / 2);
									break;
								case 2:
									line(planeSize / 2, -planeSize / 2, planeSize / 2, planeSize / 2);
									break;
								case 3:
									line(planeSize / 2, planeSize / 2, -planeSize / 2, planeSize / 2);
									break;
								case 4:
									line(-planeSize / 2, planeSize / 2, -planeSize / 2, -planeSize / 2);
									break;
							}
							// sphere(random(mySize / 500, mySize / 200) / 2);
							break;
					}

					// plane(random(mySize/10, mySize/2000));
					// box(random(mySize / 500, mySize / 200) * 1.5);
					pop();

					let px = plus / random(a, int(TAU)) / 2*b / sin(n);
					let py = plus / random(a, int(TAU)) / b / cos(n);
					let pz = plus / random(a, int(TAU)) / 5*b / tan(n);
					push();
					noStroke();
					fill(random(palette));
					translate(px, py, pz);
					sphere(mySize / 1000);
					pop();

					noFill();
					stroke(random(palette));
					strokeWeight(random(a, b) * 1 / 5 / random(1, 0.1));
					line(0, 0, 0, px, py, pz);
					noStroke();
					fill(random(palette));
					sphere(planeSize / random(5, 10));

					pop();
				}
			}
		}
	pop();
	t += 0.1 / 10;
}

function heart(x, y, size) {
  beginShape();
  vertex(x, y);
  bezierVertex(x - size / 2, y - size / 2, x - size, y + size / 3, x, y + size);
  bezierVertex(x + size, y + size / 3, x + size / 2, y - size / 2, x, y);
  endShape(CLOSE);
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("genuary-20250126", "png");
	}
}

